    @classmethod
    def define_schema(cls):
        return io.Schema(node_id="AMY_Placeholder_ThreeString_Oracle_R1",
                         display_name="Placeholder strict three-string test oracle R1",
                         category="tests/placeholder_replacer", is_output_node=True,
                         inputs=[io.String.Input("actual_resolved_prompts", force_input=True),
                                 io.String.Input("actual_debug_info", force_input=True),
                                 io.String.Input("actual_primary_ids", force_input=True),
                                 io.String.Input("expected_json", multiline=True), io.Image.Input("image")],
                         outputs=[io.Image.Output("verified_image")])

    @classmethod
    def execute(cls, actual_resolved_prompts, actual_debug_info, actual_primary_ids, expected_json, image):
        from .packmanifest import encode_schema
        from ._secure_nodes import PlaceholderReplacerByID
        if encode_schema(cls.GET_SCHEMA()) != ORACLE_SCHEMA:
            raise AssertionError("Placeholder oracle canonical schema drift")
        if encode_schema(PlaceholderReplacerByID.GET_SCHEMA()) != PRODUCTION_SCHEMA:
            raise AssertionError("Placeholder production schema literal canonical drift")
        receipt = strict_three_strings(actual_resolved_prompts, actual_debug_info, actual_primary_ids, expected_json)
        if not isinstance(image, sdk.ImageRef):
            raise AssertionError("Placeholder oracle requires an actual ImageRef")
        return io.NodeOutput(image, ui={"text": [receipt]})

