def required_weights_for(node_class: type) -> tuple[sdk.HuggingFaceWeight, ...]:
    """Return and validate a node's declarative model-weight requirements."""
    values = getattr(node_class, "SDK_REQUIRED_WEIGHTS", ())
    if values is None:
        values = ()
    if not isinstance(values, (list, tuple)):
        raise TypeError(
            f"{node_class.__name__}.SDK_REQUIRED_WEIGHTS must be a list or tuple")
    result = tuple(values)
    if not all(isinstance(item, sdk.HuggingFaceWeight) for item in result):
        raise TypeError(
            f"{node_class.__name__}.SDK_REQUIRED_WEIGHTS must contain "
            "sdk.HuggingFaceWeight declarations")
    if len(set(result)) != len(result):
        raise ValueError(
            f"{node_class.__name__}.SDK_REQUIRED_WEIGHTS contains duplicates")
    return result


def encode_required_weights(node_class: type) -> list[dict]:
    return [
        {
            "repo_id": item.repo_id,
            "filename": item.filename,
            "folder": item.folder,
            "revision": item.revision,
            "sha256": item.sha256,
            **({"on_demand": True} if item.on_demand else {}),
        }
        for item in required_weights_for(node_class)
    ]


def decode_required_weights(value: Any) -> tuple[sdk.HuggingFaceWeight, ...]:
    if not isinstance(value, list):
        raise ValueError("required_weights must be a list")
    required = {"repo_id", "filename", "folder"}
    optional = {"revision", "sha256", "on_demand"}
    result = []
    for index, item in enumerate(value):
        if not isinstance(item, dict):
            raise ValueError(
                f"required_weights[{index}] must be an object")
        keys = set(item)
        missing = required - keys
        unknown = keys - required - optional
        if missing or unknown:
            raise ValueError(
                f"required_weights[{index}] has missing fields "
                f"{sorted(missing)} and unknown fields {sorted(unknown)}")
        result.append(sdk.HuggingFaceWeight(
            repo_id=item["repo_id"],
            filename=item["filename"],
            folder=item["folder"],
            revision=item.get("revision", "main"),
            sha256=item.get("sha256"),
            on_demand=item.get("on_demand", False),
        ))
    if len(set(result)) != len(result):
        raise ValueError("required_weights contains duplicate declarations")
    return tuple(result)


def _io_class(io_type: str):
    for value in vars(io).values():
        if isinstance(value, type) and getattr(value, "io_type", None) == io_type:
            return value
    return io.Custom(io_type)


def _encode_value(value: Any):
    if isinstance(value, Enum):
        return {
            "$type": "enum",
            "enum": type(value).__name__,
            "name": value.name,
        }
    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    if isinstance(value, io_impl.Input):
        return {"$type": "input", "value": _encode_input(value)}
    if isinstance(value, io_impl.Output):
        return {"$type": "output", "value": _encode_output(value)}
    if isinstance(value, io.DynamicCombo.Option):
        return {
            "$type": "dynamic-option",
            "key": value.key,
            "inputs": [_encode_input(item) for item in value.inputs],
        }
    if isinstance(value, io.MatchType.Template):
        return {
            "$type": "match-template",
            "template_id": value.template_id,
            "allowed_types": [item.io_type for item in value.allowed_types],
        }
    if isinstance(value, io.Autogrow.TemplatePrefix):
        return {
            "$type": "autogrow-prefix",
            "input": _encode_input(value.input),
            "prefix": value.prefix,
            "min": value.min,
            "max": value.max,
        }
    if isinstance(value, io.Autogrow.TemplateNames):
        return {
            "$type": "autogrow-names",
            "input": _encode_input(value.input),
            "names": value.names,
            "min": value.min,
        }
    if isinstance(value, io.RemoteOptions):
        return {"$type": "remote-options", "attrs": _encode_value(vars(value))}
    if isinstance(value, type) and getattr(value, "io_type", None):
        return {"$type": "io-class", "io_type": value.io_type}
    if isinstance(value, tuple):
        return {"$type": "tuple", "items": [_encode_value(item) for item in value]}
    if isinstance(value, list):
        return [_encode_value(item) for item in value]
    if isinstance(value, dict):
        return {str(key): _encode_value(item) for key, item in value.items()}
    raise TypeError(f"manifest cannot encode {type(value).__name__}")


def _decode_value(value: Any):
    if isinstance(value, list):
        return [_decode_value(item) for item in value]
    if not isinstance(value, dict):
        return value
    tag = value.get("$type")
    if tag is None:
        return {key: _decode_value(item) for key, item in value.items()}
    if tag == "input":
        return _decode_input(value["value"])
    if tag == "output":
        return _decode_output(value["value"])
    if tag == "dynamic-option":
        return io.DynamicCombo.Option(
            value["key"], [_decode_input(item) for item in value["inputs"]])
    if tag == "match-template":
        return io.MatchType.Template(
            value["template_id"],
            [_io_class(item) for item in value["allowed_types"]],
        )
    if tag == "autogrow-prefix":
        return io.Autogrow.TemplatePrefix(
            _decode_input(value["input"]), value["prefix"],
            value["min"], value["max"])
    if tag == "autogrow-names":
        return io.Autogrow.TemplateNames(
            _decode_input(value["input"]), value["names"], value["min"])
    if tag == "remote-options":
        remote = object.__new__(io.RemoteOptions)
        remote.__dict__.update(_decode_value(value["attrs"]))
        return remote
    if tag == "io-class":
        return _io_class(value["io_type"])
    if tag == "enum":
        enum_type = getattr(io, value["enum"], None)
        if not isinstance(enum_type, type) or not issubclass(enum_type, Enum):
            raise ValueError(f"unknown manifest enum {value['enum']!r}")
        return enum_type[value["name"]]
    if tag == "tuple":
        return tuple(_decode_value(item) for item in value["items"])
    raise ValueError(f"unknown manifest value tag {tag!r}")


def _input_kind(value: io_impl.Input) -> str:
    if isinstance(value, io.DynamicCombo.Input):
        return "dynamic-combo"
    if isinstance(value, io.Autogrow.Input):
        return "autogrow"
    if isinstance(value, io.MatchType.Input):
        return "match-type"
    if isinstance(value, io.MultiType.Input):
        return "multi-type"
    return "standard"


def _encode_input(value: io_impl.Input) -> dict:
    return {
        "kind": _input_kind(value),
        "io_type": value.io_type,
        "attrs": _encode_value(vars(value)),
    }


def _decode_input(value: dict) -> io_impl.Input:
    kind = value["kind"]
    if kind == "dynamic-combo":
        cls = io.DynamicCombo.Input
    elif kind == "autogrow":
        cls = io.Autogrow.Input
    elif kind == "match-type":
        cls = io.MatchType.Input
    elif kind == "multi-type":
        cls = io.MultiType.Input
    elif kind == "standard":
        cls = _io_class(value["io_type"]).Input
    else:
        raise ValueError(f"unknown manifest input kind {kind!r}")
    result = object.__new__(cls)
    result.__dict__.update(_decode_value(value["attrs"]))
    return result


def _encode_output(value: io_impl.Output) -> dict:
    return {
        "kind": "match-type" if isinstance(value, io.MatchType.Output)
        else "standard",
        "io_type": value.io_type,
        "attrs": _encode_value(vars(value)),
    }


def _decode_output(value: dict) -> io_impl.Output:
    if value["kind"] == "match-type":
        cls = io.MatchType.Output
    elif value["kind"] == "standard":
        cls = _io_class(value["io_type"]).Output
    else:
        raise ValueError(f"unknown manifest output kind {value['kind']!r}")
    result = object.__new__(cls)
    result.__dict__.update(_decode_value(value["attrs"]))
    return result


def encode_schema(schema: io.Schema) -> dict:
    scalars = {
        key: _encode_value(value)
        for key, value in vars(schema).items()
        if key not in {"inputs", "outputs", "hidden"}
    }
    return {
        "attrs": scalars,
        "inputs": [_encode_input(value) for value in schema.inputs],
        "outputs": [_encode_output(value) for value in schema.outputs],
        "hidden": [value.name for value in schema.hidden],
    }


def decode_schema(value: dict) -> io.Schema:
    attrs = _decode_value(value["attrs"])
    attrs["inputs"] = [_decode_input(item) for item in value["inputs"]]
    attrs["outputs"] = [_decode_output(item) for item in value["outputs"]]
    attrs["hidden"] = [io.Hidden[name] for name in value["hidden"]]
    return io.Schema(**attrs)

